import{_ as p,a0 as r,w as i,s as a,ao as d,I as t,x as e,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"安卓编年史（11）：The Nexus One——迎来 Google Phone | LCTT x X-CMD","titleTemplate":false,"description":"安卓编年史（11）：The Nexus One——迎来 Google Phone | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓编年史（11）：The Nexus One——迎来 Google Phone | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓编年史（11）：The Nexus One——迎来 Google Phone | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/11 - The history of Android","title":"安卓编年史（11）：The Nexus One——迎来 Google Phone","tag":"The history of Android","desc":""},"relativePath":"The history of Android/11 - The history of Android.md","filePath":"[post].md"}'),u={name:"The history of Android/11 - The history of Android.md"};function m(g,o,h,f,T,x){const n=r("Link");return i(),a("div",null,[o[26]||(o[26]=d('<h1 id="安卓编年史-11-the-nexus-one——迎来-google-phone" tabindex="-1">安卓编年史（11）：The Nexus One——迎来 Google Phone <a class="header-anchor" href="#安卓编年史-11-the-nexus-one——迎来-google-phone" aria-label="Permalink to “安卓编年史（11）：The Nexus One——迎来 Google Phone”">​</a></h1><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/dialercontacts.png" alt="重新设计的拨号和联系人页面。"></p><p><em>重新设计的拨号和联系人页面。 [Ron Amadeo 供图]</em></p><p>联系人/拨号应用程序的圆角标签拥有了更清晰、更成熟的外观设计。拨号器更名为“电话”，并且拨号按键从圆形改为了圆角矩形。语音邮件、拨号、以及删除按键被放置在底部。这个界面是安卓在 3.0 之前缺乏设计一致性的一个很好的例子。仅仅在这个界面上，标签用的是直角矩形，拨号按键使用圆角矩形，底部按键两侧合起来是个完整的圆。这里就像是个 UI 控件的摸奖袋，没有人尝试过让它们之间相互搭配。</p><p>安卓 2.0 的一个新特性是“快速拨号”，它将联系人以略缩图的形式添加到整个系统。从其它应用中点击它们可以打开一个联系这个人的快捷方式列表。这在联系人里并没有多大意义，但像在 Google Talk 中，能够通过点击某人的略缩图来给他拨号是十分方便的。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/calls.png" alt=""></p><p><em>[Ron Amadeo 供图]</em></p><p>安卓 2.0 终于配备了接通和拒绝来电所需要的所有屏幕按键，而不再需要实体按钮，Droid 从中获益，从它的设计中除去了在现在看来是多余的按钮。安卓对于接通和拒绝来电的解决方案是这些左滑和右滑的标签。他们的工作方式就像是滑动解锁（后来被用到了滑动解锁中）——向右滑动绿色按钮接通来电，向左滑动红色按钮则是拒绝。一旦进入通话中，它看起来就很像安卓 1.6 了。所有选项还是隐藏在菜单按钮之中。</p><p>某人在设计拨号界面的时候一定在煲电话粥。他们只是去掉了“拨号盘”上字母的粗体，而不是从安卓 1.6 中重新绘制数字“5”的按键，然后就这么收工了。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/01/calcubrowser.png" alt="计算器和浏览器"></p><p><em>计算器和浏览器 [Ron Amadeo 供图]</em></p><p>计算器从在安卓 0.9 中被引入以来第一次得到改进。黑色玻璃球按钮换成了蓝色和黑色过渡的按钮。旧版计算器按键的按下高亮的红色边框被改为了一个比较正常的白色轮廓。</p><p>浏览器的微型网站名称栏改进为一个完整的、功能更完善的地址栏，并且带有书签按钮。为了节省屏幕空间，地址栏被附加到网页上，所以地址栏会随着页面向上滚动，给你留下更多的网页阅读空间。安卓 1.6 独特的缩放控制和附加按钮被去除，被替换为一个更简单的双击缩放手势，并且浏览器可以再次打开 arstechnica.com 而不崩溃了。这里还是没有双指捏合缩放。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/cam2-these-are-settigns.jpg" alt="打开设置的相机，闪光灯设置，以及查看照片界面的菜单。"></p><p><em>打开设置的相机，闪光灯设置，以及查看照片界面的菜单。 [Ron Amadeo 供图]</em></p><p>相机应用有个布满整个左侧的抽屉式菜单，打开它有许多设置。摩托罗拉 Droid 是率先带有 LED 闪光灯的安卓手机之一，所以设置里有个闪光灯控制，以及还有像场景模式、白平衡、效果、图片尺寸和存储位置（SD 卡或内置存储）的设置。</p><p>在照片查看界面，谷歌精简了菜单按钮。和屏幕上的选项相比，它们之间不再有重复的选项。这样精简后省下的空间，使得所有的选项能够在菜单里放得下了，而不再需要一个“更多”按钮。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/emailacc2ountsetc.png" alt="电子邮件应用的“帐户”页面，新的组合收件箱，系统设置的帐户与同步页面，自动亮度设置。 "></p><p><em>电子邮件应用的“帐户”页面，新的联合收件箱，系统设置的帐户与同步页面，自动亮度设置。 [Ron Amadeo 供图]</em></p><p>电子邮件应用程序有了大的功能提升。最重要的是它终于支持了 Microsoft Exchange。安卓 2.0 版本的电子邮件中收件箱和文件夹视图终于分开了，而不是使用安卓 1.0 引入的凌乱的混合视图。电子邮件甚至有了一个统一的收件箱，可以将你不同账户的所有邮件显示到一起。</p><p>这个收件箱视图和 Gmail 一起，把普通的电子邮件应用打趴下了。联合收件箱甚至胜过了 Gmail 的功能，这是极其罕见的。尽管如此，相对于 Gmail 来说，电子邮件仍然感觉像个多余的继女。它使用了 Gmail 界面来查看邮件，这意味着收件箱和文件夹使用了黑色主题，查看邮件却奇怪地选择了亮色主题。</p>',21)),t("p",null,[o[1]||(o[1]=e("捆绑的 Facebook 应用程序有一个很棒的账户同步功能，它可以从社交网络上下载联系人的照片和信息，并无缝集成到联系人应用里。后来 Facebook 和谷歌分道扬镳，",-1)),s(n,{href:"http://techcrunch.com/2011/02/22/google-android-facebook-contacts/"},{default:l(()=>[...o[0]||(o[0]=[e("谷歌取消了这一功能",-1)])]),_:1}),o[2]||(o[2]=e("。谷歌表示，在 Facebook 不向其共享信息的情况下，与 Facebook 分享信息并不是什么好想法，因此更好的用户体验败给了公司间的政治斗争。",-1))]),o[27]||(o[27]=t("p",null,"（不幸的是，我们无法展示 Facebook 应用，因为它也是死在 OAuth 更新手中的客户端之一。现在不可能从像这么老旧的应用上登录了。）",-1)),o[28]||(o[28]=t("p",null,"最后一张图片显示了自动亮度控制，安卓 2.0 是第一个支持这一功能的版本。Droid 配备了光线传感器，点击该复选框，会使亮度滑块消失，并且允许设备自动控制屏幕亮度。",-1)),o[29]||(o[29]=t("p",null,"正如它的名字所暗示的那样，安卓 2.0 是谷歌有史以来最大的更新。摩托罗拉和威瑞森给安卓带来了一个外形酷炫的设备，并在广告上投入了数不清的资金。之后的一段时间里，“Droid”成为了一个家喻户晓的名字。",-1)),o[30]||(o[30]=t("h3",{id:"the-nexus-one——迎来-google-phone",tabindex:"-1"},[e("The Nexus One——迎来 Google Phone "),t("a",{class:"header-anchor",href:"#the-nexus-one——迎来-google-phone","aria-label":"Permalink to “The Nexus One——迎来 Google Phone”"},"​")],-1)),o[31]||(o[31]=t("p",null,[t("img",{src:"http://cdn.arstechnica.net/wp-content/uploads/2014/03/nexus_4_lineup.jpg",alt:""})],-1)),t("p",null,[o[4]||(o[4]=e("2010 年 1 月，第一款 Nexus 设备发布，称为“",-1)),s(n,{href:"http://arstechnica.com/gadgets/2010/01/nexus-one-review/"},{default:l(()=>[...o[3]||(o[3]=[e("Nexus One",-1)])]),_:1}),o[5]||(o[5]=e("”。对谷歌来说，这部设备是个巨大的里程碑。这是第一部由谷歌设计并冠名的设备，而且谷歌计划直接向消费者出售设备。宏达电代工的 Nexus One 拥有 1GHz 的单核高通骁龙 S1 处理器、512MB 的内存、512MB 存储空间，以及一块 3.7 英寸的 AMOLED 显示屏。",-1))]),o[32]||(o[32]=t("p",null,"Nexus One 代表着拥有纯净的安卓体验，没有运营商的定制和应用植入。谷歌直接控制安卓的更新。这使得谷歌能够在软件完成时直接向用户进行推送， 而不是再经过运营商的许可。运营商总是拖慢这一过程，因为他们对用户已经付过钱手机并不总是那么热切地想要改善它们。",-1)),t("p",null,[o[7]||(o[7]=e("谷歌",-1)),s(n,{href:"http://arstechnica.com/gadgets/2010/01/googles-big-news-today-was-not-a-phone-but-a-url/"},{default:l(()=>[...o[6]||(o[6]=[e("直接在网上",-1)])]),_:1}),o[8]||(o[8]=e("销售 Nexus One，无锁、无合约、完整零售价 529.99 美元。尽管同样的 Nexus One 在 T-Mobile 商店的合约价仅为 179.99 美元，谷歌想通过它的在线商店改变美国手机行业的运作方式。谷歌当时的想法是先挑选手机，再选择运营商，以此打破美国无线寡头对硬件的控制。",-1))]),o[33]||(o[33]=t("p",null,"但谷歌的零售革命并没有奏效，在在线手机商店开通半年后，谷歌关闭了该服务。谷歌指出首要问题是销量低。在 2010 年，网上购物并不像今天这样司空见惯，消费者也还没有准备好在他们不能先握在自己手中试用的设备上花费 530 美元。高昂的价格也是一个制约因素；智能手机消费者更习惯于为眼前的设备花费 200 美元，并签署一项为期两年的合同。还有摩托罗拉 Droid 的因素，相比之下这部三个月前发布的设备并没有显著的不足。还由于 Droid 的庞大的营销活动和“iPhone 杀手”的炒作，它已经夺取了大多数 Nexus One 所面向的安卓发烧友市场。",-1)),t("p",null,[o[10]||(o[10]=e("尽管 Nexus One 的网上销售尝试可以被认为是失败的，谷歌还是从中学到了很多。2012 年，谷歌以 Google Play 的“设备”板块",-1)),s(n,{href:"http://arstechnica.com/gadgets/2012/04/unlocked-samsung-galaxy-nexus-can-now-be-purchased-from-google/"},{default:l(()=>[...o[9]||(o[9]=[e("重新推出其网上商店",-1)])]),_:1}),o[11]||(o[11]=e("。",-1))]),o[34]||(o[34]=t("hr",null,null,-1)),o[35]||(o[35]=t("p",null,[t("img",{src:"http://cdn.arstechnica.net/wp-content//uploads/authors/ron-amadeo-sq.jpg",alt:"Ron Amadeo"})],-1)),t("p",null,[s(n,{href:"http://arstechnica.com/author/ronamadeo"},{default:l(()=>[...o[12]||(o[12]=[e("Ron Amadeo",-1)])]),_:1}),o[14]||(o[14]=e(" / Ron 是 Ars Technica 的评论编缉，专注于安卓系统和谷歌产品。他总是在追寻新鲜事物，还喜欢拆解事物看看它们到底是怎么运作的。",-1)),s(n,{href:"https://twitter.com/RonAmadeo"},{default:l(()=>[...o[13]||(o[13]=[e("@RonAmadeo",-1)])]),_:1})]),o[36]||(o[36]=t("hr",null,null,-1)),t("p",null,[o[16]||(o[16]=e("via: ",-1)),s(n,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/11/"},{default:l(()=>[...o[15]||(o[15]=[e("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/11/",-1)])]),_:1})]),t("p",null,[o[19]||(o[19]=e("译者：",-1)),s(n,{href:"https://github.com/alim0x"},{default:l(()=>[...o[17]||(o[17]=[e("alim0x",-1)])]),_:1}),o[20]||(o[20]=e(" 校对：",-1)),s(n,{href:"https://github.com/wxy"},{default:l(()=>[...o[18]||(o[18]=[e("wxy",-1)])]),_:1})]),t("p",null,[o[23]||(o[23]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[21]||(o[21]=[e("LCTT",-1)])]),_:1}),o[24]||(o[24]=e(" 原创翻译，",-1)),s(n,{href:"http://linux.cn/"},{default:l(()=>[...o[22]||(o[22]=[e("Linux中国",-1)])]),_:1}),o[25]||(o[25]=e(" 荣誉推出",-1))])])}const w=p(u,[["render",m]]);export{b as __pageData,w as default};
